   733→function loadPackageCourseTeachers(packageId) {
   734→    const summaryBox = document.getElementById('pkgTeacherSummary');
   735→    const listEl     = document.getElementById('pkgTeacherList');
   736→    if (!summaryBox || !listEl) return;
   737→
   738→    if (!packageId) {
   739→        summaryBox.style.display = 'none';
   740→        listEl.innerHTML = '<span class="text-muted" style="font-size:13px">Pilih paket standar terlebih dahulu.</span>';
   741→        return;
   742→    }
   743→
   744→    listEl.innerHTML = '<span class="text-muted" style="font-size:13px"><i class="bi bi-hourglass-split me-1"></i>Memuat data guru...</span>';
   745→    summaryBox.style.display = '';
