   747→    fetch(`/admin/course-package/${packageId}/course-teachers`, {
   748→        headers: { 'Accept': 'application/json', 'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').content }
   749→    })
   750→    .then(r => { if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); })
   751→    .then(data => {
   752→        const courses = data.courses || [];
   753→        if (!courses.length) {
   754→            listEl.innerHTML = '<span class="text-muted" style="font-size:13px">Paket ini belum memiliki mata pelajaran.</span>';
   755→            return;
   756→        }
   757→
   758→        const hasAssignments = courses.some(c => c.teachers && c.teachers.length > 0);
   759→
   760→        if (!hasAssignments) {
   761→            listEl.innerHTML = '<span class="text-muted" style="font-size:13px"><i class="bi bi-info-circle me-1"></i>Paket ini belum memiliki penetapan guru per mata pelajaran. Silakan pilih guru dari dropdown di bawah.</span>';
   762→            return;
